<script lang="ts">

 import SourceReader from '$lib/components/harness/SourceReader.svelte';
 import Icon from '$lib/components/harness/Icon.svelte';
 import {goto} from '$app/navigation';
 import {onMount} from 'svelte';
 import {dateLabel} from '$lib/harness/types';
 import type {GitHubSnapshot} from '$lib/server/github-harness';
 import type {PageData} from './$types';
 let {data}:{data:PageData}=$props();
 let url=$state(''),title=$state(''),description=$state(''),topic=$state('workflow'),snapshot=$state<GitHubSnapshot|null>(null),error=$state(''),loading=$state(false),publishing=$state(false);
 async function preview(event?:SubmitEvent){event?.preventDefault();loading=true;error='';snapshot=null;try{const res=await fetch('/api/harnesses/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url})});const body=await res.json();if(!res.ok)throw new Error(body.error);snapshot=body.snapshot;if(!title)title=`${body.snapshot.owner}’s ${body.snapshot.path.split('/').at(-1)}`;}catch(e){error=e instanceof Error?e.message:'The file could not be read.';}finally{loading=false;}}
 function keepDraft(){try{sessionStorage.setItem('loooom-context-draft',JSON.stringify({url,title,description,topic}));}catch{ /* The form still works when browser storage is unavailable. */ }}
 onMount(()=>{try{const raw=sessionStorage.getItem('loooom-context-draft');if(raw){const draft=JSON.parse(raw);if(typeof draft.url==='string')url=draft.url;if(typeof draft.title==='string')title=draft.title;if(typeof draft.description==='string')description=draft.description;if(['workflow','coding','design','testing'].includes(draft.topic))topic=draft.topic;}}catch{ /* Ignore an expired draft. */ }});
 async function publish(event:SubmitEvent){event.preventDefault();publishing=true;error='';try{const {auth}=await import('$lib/firebase');await auth.authStateReady();if(!auth.currentUser)throw new Error('Sign in first, then preview your file again.');const res=await fetch('/api/harnesses',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${await auth.currentUser.getIdToken()}`},body:JSON.stringify({url:snapshot?.sourceUrl,expectedCommitSha:snapshot?.commitSha,title,description,topic})});const body=await res.json();if(!res.ok)throw new Error(body.error);sessionStorage.removeItem('loooom-context-draft');await goto(`/h/${body.id}`);}catch(e){error=e instanceof Error?e.message:'Sharing failed. Try again.';}finally{publishing=false;}}
</script>
<svelte:head><title>Share your AGENTS.md — Loooom</title><meta name="description" content="Share AGENTS.md from GitHub, with optional Markdown context."/></svelte:head>
<div class="page-intro"><a href="/" class="back-link">Browse harnesses <Icon name="arrow" size={14}/></a><h1>Share your<br/><span>AGENTS.md.</span></h1><p>Link your rules on GitHub. Other context is optional.</p></div>
 <div class="share-layout"><div class="share-main"><form onsubmit={preview} class="import-form"><label for="github-url">Your GitHub file link</label><p>AGENTS.md, or another public Markdown file.</p><div class="url-input"><Icon name="github" size={20}/><input id="github-url" type="url" required maxlength="2048" bind:value={url} placeholder="https://github.com/you/context/blob/main/AGENTS.md"/></div><button class="button primary" disabled={loading||publishing} type="submit">{loading?'Reading from GitHub…':'Preview your file'}<Icon name="arrow" size={16}/></button></form>
 {#if error}<div class="notice error" role="alert">{error}</div>{/if}
 {#if !data.storageAvailable}<p class="notice">Publishing is unavailable here. You can preview a public file without changing it.</p>{/if}
 {#if snapshot}<section class="preview-section" aria-label="Import preview"><div class="preview-meta"><span><Icon name="check" size={15}/> File found</span><span>{snapshot.lineCount} lines</span><code>{snapshot.commitSha.slice(0,7)}</code><span>Updated {dateLabel(snapshot.updatedAt)}</span></div><SourceReader content={snapshot.content} filename={snapshot.path}/><form class="publish-form" onsubmit={publish}><h2>Add a note.</h2><label for="title">Title</label><input id="title" bind:value={title} required maxlength="100"/><label for="description">Why this file?</label><textarea id="description" bind:value={description} maxlength="400" rows="3" placeholder="What works, and what needs work?"></textarea><label for="topic">Topic</label><select id="topic" bind:value={topic}>{#each ['workflow','coding','design','testing'] as item}<option value={item}>{item}</option>{/each}</select><p>This file and note will be public. Source owner and sharer get separate credit. Check the preview first.</p>{#if data.user}<button class="button primary" type="submit" disabled={publishing||!data.storageAvailable}>{publishing?'Sharing…':'Share this file'}<Icon name="arrow" size={16}/></button>{:else}<a class="button primary" href="/login?next=/share" onclick={keepDraft}>Sign in to share<Icon name="arrow" size={16}/></a>{/if}</form></section>{/if}</div>
 <aside class="share-guide"><h2>Start with your rules.</h2><div><Icon name="code" size={19}/><h3>AGENTS.md</h3><p>Rules, tools, and working standards.</p></div><p class="optional-note">More context, if you want:</p><div><Icon name="people" size={19}/><h3>ME.md</h3><p>The personal context you choose to share.</p></div><div><Icon name="heart" size={19}/><h3>SOUL.md</h3><p>Your agent's character. Borrow ideas, not an identity.</p></div><div><Icon name="layers" size={19}/><h3>DESIGN.md</h3><p>Design rules and visual standards.</p></div><a class="text-link" href="/me/edit">Build your ME.md <Icon name="arrow" size={15}/></a><section><h3>Pinned to the source.</h3><p>Imports keep the commit, date, line count, and contents. After an edit, use “Refresh from GitHub”.</p></section></aside></div>

