 .page-intro h1 span{color:var(--lime)}.share-layout{display:grid;grid-template-columns:minmax(0,1fr) 270px;gap:55px;padding-bottom:20px}.share-main{min-width:0}.import-form{padding:28px;background:var(--panel);border:1px solid var(--line);border-radius:10px}.import-form label{font-size:18px;font-weight:500}.import-form p{font-size:12px;color:var(--quiet);margin:7px 0 20px}.url-input{display:flex;align-items:center;gap:13px;border:1px solid var(--line-strong);background:var(--ink);border-radius:6px;padding:14px;margin-bottom:20px;color:var(--quiet)}.url-input input{min-width:0;width:100%;background:transparent;border:0;color:var(--paper);font-size:12px}.url-input input::placeholder{color:var(--quiet)}.share-guide h2{font-size:23px;margin:0 0 25px}.share-guide>div{position:relative;padding-left:30px;margin-bottom:25px}.share-guide>div>:global(svg){position:absolute;left:0;top:2px;color:var(--lime)}.share-guide>div:nth-child(3)>:global(svg){color:var(--lavender)}.share-guide h3{font-size:14px;margin:0 0 7px}.share-guide p{color:var(--quiet);font-size:13px;line-height:1.7}.share-guide section{border-top:1px solid var(--line);padding-top:25px;margin-top:30px}.preview-section{margin-top:24px}.preview-meta{display:flex;align-items:center;gap:16px;flex-wrap:wrap;font-size:11px;margin-bottom:14px;color:var(--quiet)}.preview-meta span:first-child{color:var(--lime);display:flex;gap:6px;align-items:center}.publish-form{margin-top:35px;display:flex;flex-direction:column;align-items:flex-start;gap:10px}.publish-form h2{margin:0 0 10px}.publish-form label{font-size:13px;margin-top:10px}.publish-form input,.publish-form textarea,.publish-form select{width:100%;padding:12px;background:var(--panel);border:1px solid var(--line);color:var(--paper);border-radius:6px}.publish-form textarea{resize:vertical}.publish-form p{font-size:12px;color:var(--quiet);line-height:1.7;margin:10px 0}.publish-form select{max-width:220px}@media(max-width:1100px){.share-layout{grid-template-columns:1fr;gap:35px}.share-guide{max-width:600px}.import-form{padding:22px}}@media(max-width:760px){.import-form{padding:19px}.import-form p{font-size:11px}.url-input{padding:12px;gap:8px}.url-input input{font-size:11px}}
 .share-guide .optional-note{margin:0 0 20px;font-size:12px}
</style>
